-- UI/TabNullaeus.lua
L["The Nemesis Delve"] = "Die Nemesis-Tiefe"
L["Season 2 Nemesis  \226\128\148  two difficulties, Tier \"?\" and Tier \"??\""] = "Nemesis der Saison 2  —  zwei Schwierigkeitsgrade, Stufe \"?\" und Stufe \"??\""
